import React, { useEffect, useState, useCallback } from 'react';
import invoiceService from '../../services/invoiceService';
import reservationService from '../../services/reservationService';
import PageHeader from '../../components/common/PageHeader';
import DataTable from '../../components/common/DataTable';
import Modal from '../../components/common/Modal';
import StatusBadge from '../../components/common/StatusBadge';
import '../../components/common/shared.css';

const InvoicesPage = () => {
  const [invoices, setInvoices]         = useState([]);
  const [reservations, setReservations] = useState([]);
  const [loading, setLoading]           = useState(true);
  const [modal, setModal]               = useState(false);
  const [selectedRes, setSelectedRes]   = useState('');
  const [generating, setGenerating]     = useState(false);

  const load = useCallback(() => {
    setLoading(true);
    Promise.allSettled([
      invoiceService.getAll(),
      reservationService.getAll({ status: 'checked_out' }),
    ]).then(([inv, res]) => {
      if (inv.status === 'fulfilled') setInvoices(inv.value);
      if (res.status === 'fulfilled') setReservations(res.value);
      setLoading(false);
    });
  }, []);

  useEffect(() => { load(); }, [load]);

  const handleGenerate = async () => {
    if (!selectedRes) return;
    setGenerating(true);
    try {
      await invoiceService.generate(selectedRes);
      setModal(false);
      setSelectedRes('');
      load();
    } catch (err) {
      alert(err.message || 'Erreur lors de la génération');
    } finally {
      setGenerating(false);
    }
  };

  const handleDownload = async (id) => {
    try {
      const blob = await invoiceService.download(id);
      const url  = URL.createObjectURL(blob);
      const a    = document.createElement('a');
      a.href     = url;
      a.download = `facture-${id}.pdf`;
      a.click();
      URL.revokeObjectURL(url);
    } catch {
      alert('Téléchargement indisponible');
    }
  };

  const columns = [
    { key: 'id', label: 'N°', render: r => `#${r.id}` },
    { key: 'client', label: 'Client', render: r => r.client?.name ?? `#${r.client_id}` },
    { key: 'reservation_id', label: 'Réservation', render: r => `#${r.reservation_id ?? '—'}` },
    { key: 'total', label: 'Montant', render: r => `${r.total ?? '—'} €` },
    { key: 'created_at', label: 'Date', render: r => new Date(r.created_at).toLocaleDateString('fr-FR') },
    { key: 'status', label: 'Statut', render: r => <StatusBadge status={r.status ?? 'unpaid'} /> },
  ];

  // Reservations without invoice
  const uninvoiced = reservations.filter(r =>
    !invoices.find(i => i.reservation_id === r.id)
  );

  return (
    <div>
      <PageHeader
        title="Facturation"
        subtitle={`${invoices.length} facture${invoices.length > 1 ? 's' : ''} générées`}
        action={
          <button className="btn btn--primary" onClick={() => setModal(true)}>
            + Générer une facture
          </button>
        }
      />

      <DataTable
        columns={columns}
        data={invoices}
        loading={loading}
        empty="Aucune facture générée."
        actions={row => (
          <button className="btn btn--sm btn--outline" onClick={() => handleDownload(row.id)}>
            ⬇ PDF
          </button>
        )}
      />

      {modal && (
        <Modal title="Générer une facture" onClose={() => setModal(false)} size="sm">
          <div className="form-group" style={{ marginBottom: '1.25rem' }}>
            <label className="form-label">Sélectionner la réservation (checkout)</label>
            <select
              className="form-select"
              value={selectedRes}
              onChange={e => setSelectedRes(e.target.value)}
            >
              <option value="">— choisir —</option>
              {uninvoiced.map(r => (
                <option key={r.id} value={r.id}>
                  #{r.id} — {r.client?.name ?? `Client #${r.client_id}`} — Ch. {r.room?.number ?? r.room_id}
                </option>
              ))}
            </select>
          </div>
          <div className="form-actions">
            <button className="btn btn--outline" onClick={() => setModal(false)}>Annuler</button>
            <button
              className="btn btn--gold"
              disabled={!selectedRes || generating}
              onClick={handleGenerate}
            >
              {generating ? <span className="dt-spinner" /> : 'Générer'}
            </button>
          </div>
        </Modal>
      )}
    </div>
  );
};

export default InvoicesPage;
